// stlport
//
// Out-of-line copies of Matrix3D::Rotate_Y(float) (0x0008533A) and
// Matrix3D::Rotate_Z(float) (0x00098CC0). Retail holds one size-optimised
// (/O1) copy of each; compiled that way the header bodies are unique masked
// whole-.text matches. The member-pointer constants below only make this TU
// emit the two inline bodies; they are not retail data.
//
#include "PreRTS.h"
#include "WWMath/matrix3d.h"

extern void (Matrix3D::*const g_bfmeRotateYAnchor)(float);
extern void (Matrix3D::*const g_bfmeRotateZAnchor)(float);
void (Matrix3D::*const g_bfmeRotateYAnchor)(float) = &Matrix3D::Rotate_Y;
void (Matrix3D::*const g_bfmeRotateZAnchor)(float) = &Matrix3D::Rotate_Z;
